                            raise FloatingPointError(
                                "non-finite value encountered during boosting"
                            )
                        terms.append(term)
                    try:
                        score = math.fsum(terms)
                    except (OverflowError, ValueError) as exc:
                        raise FloatingPointError(
                            "non-finite value encountered during boosting"
                        ) from exc
                    if not math.isfinite(score):
                        raise FloatingPointError(
                            "non-finite value encountered during boosting"
